window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-016"]={"USP17L8":{"coreEvidence":[],"near_known_relatives":[{"symbol":"USP17L2","accession":"Q6R6M4","identity":0.962,"qcov":1.0,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":["14699124","17109758","19188362","20147298","20228808","20368735","20388806","21239494","21448158"],"function":"Deubiquitinating enzyme that removes conjugated ubiquitin from specific proteins to regulate different cellular processes. Regulates cell proliferation by deubiquitinating and inhibiting RCE1 thereby controlling the small GTPases NRAS and HRAS localization and activation. In parallel, mediates deubiquitination of CDC25A, preventing CDC25A degradation by the proteasome during the G1/S and G2/M phases promoting cell-cycle progression. Also regulates cell proliferation and apoptosis through deubiquitination of SUDS3 a regulator of histone deacetylation. Through activation of the Rho family GTPases RAC1A, CDC42 and RHOA, regulates cell migration. Through the cleavage of 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains of the cytoplasmic innate immune receptors RIGI and IFIH1 stimulates the cellular response to viral infection","member_mechanism_evidence_available":true},{"symbol":"USP17L24","accession":"Q0WX57","identity":0.939,"qcov":1.0,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"NUTM2F":{"coreEvidence":[{"partner":"EP300","hgnc":"HGNC:3373","core":true,"core_annotation":{"hgnc":"HGNC:3373","symbol_at_source":"EP300","accession":"Q09472","function":"Histone modification write","target":"histone","pmids":["17065153"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1188,"hub_weight":0.2009669677645352,"quality":0.65,"programmes":["pubmed:35016035"],"pmids":["35016035"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293flp-in embryonic kidney cell\", \"human-293flp-in\"]"],"partner_location":"Cytoplasm; Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a histone acetyltransferase and regulates transcription via chromatin remodeling (PubMed:23415232, PubMed:23934153, PubMed:40240600, PubMed:8945521). Acetylates all four core histones in nucleosomes (PubMed:23415232, PubMed:23934153, PubMed:8945521). Histone acetylation gives an epigenetic tag for transcriptional activation (PubMed:23415232, PubMed:23934153, PubMed:8945521). Mediates acetylation of histone H3 at 'Lys-122' (H3K122ac), a modification that localizes at the surface of the histone octamer and stimulates transcription, possibly by promoting nucleosome instability (PubMed:23415232). Mediates acetylation of histone H3 at 'Lys-18' and 'Lys-27' (H3K18ac and H3K27ac, respectively) (PubMed:21131905, PubMed:23911289). Also able to acetylate histone lysine residues that are already monomethylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Catalyzes formation of histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000). In response to DNA damage, catalyzes acetylation of histone H1 at 'Lys-75' (H1K75ac) following histone H1 deamidation by CTPS1, increasing chromatin accessibility to facilitate the recruitment of DNA repair proteins (PubMed:40240600). Also functions as acetyltransferase for non-histone targets, such as ALX1, HDAC1, PRDM16, PRMT1, SIRT2, STAT3, ZNF76 or GLUL (PubMed:12929931, PubMed:15653507, PubMed:16285960, PubMed:16337145, PubMed:16762839, PubMed:18722353, PubMed:18782771, PubMed:26990986). Acetylates 'Lys-131' of ALX1 and acts as its coactivator (PubMed:12929931). Acetylates SIRT2 and is proposed to indirectly increase the transcriptional activity of p53/TP53 through acetylation and subsequent attenuation of SIRT2 deacetylase function (PubMed:18722353). Following DNA damage, forms a stress-responsive p53/TP53 coactivator complex with JMY which mediates p53/TP53 acetylation, thereby increasing p53/TP53-dependent transcription and apoptosis (PubMed:11511361, PubMed:15448695). Promotes chromatin acetylation in heat shock responsive HSP genes during the heat shock response (HSR), thereby stimulating HSR transcription (PubMed:18451878). Acetylates HDAC1 leading to its inactivation and modulation of transcription (PubMed:16762839). Acetylates 'Lys-247' of EGR2 (By similarity). Acts as a TFAP2A-mediated transcriptional coactivator in presence of CITED2 (PubMed:12586840). Plays a role as a coactivator of NEUROD1-dependent transcription of the secretin and p21 genes and controls terminal differentiation of cells in the intestinal epithelium. Promotes cardiac myocyte enlargement (PubMed:14752053). Can also mediate transcriptional repression. Acetylates FOXO1 and enhances its transcriptional activity (PubMed:15890677). Acetylates STAT3 at different sites, promoting both STAT3 dimerization and activation and recruitment to chromatin (PubMed:15653507, PubMed:16285960, PubMed:18782771). Acetylates BCL6 which disrupts its ability to recruit histone deacetylases and hinders its transcriptional repressor activity (PubMed:12402037). Participates in CLOCK or NPAS2-regulated rhythmic gene transcription; exhibits a circadian association with CLOCK or NPAS2, correlating with increase in PER1/2 mRNA and histone H3 acetylation on the PER1/2 promoter (PubMed:14645221). Acetylates MTA1 at 'Lys-626' which is essential for its transcriptional coactivator activity (PubMed:16617102). Acetylates XBP1 isoform 2; acetylation increases protein stability of XBP1 isoform 2 and enhances its transcriptional activity (PubMed:20955178). Acetylates PCNA; acetylation promotes removal of chromatin-bound PCNA and its degradation during nucleotide excision repair (NER) (PubMed:24939902). Acetylates MEF2D (PubMed:21030595). Acetylates and stabilizes ZBTB7B protein by antagonizing ubiquitin conjugation and degradation, this mechanism may be involved in CD4/CD8 lineage differentiation (PubMed:20810990). Acetylates GABPB1, impairing GABPB1 heterotetramerization and activity (By similarity). Acetylates PCK1 and promotes PCK1 anaplerotic activity (PubMed:30193097). Acetylates RXRA and RXRG (PubMed:17761950). Acetylates isoform M2 of PKM (PKM2), promoting its homodimerization and conversion into a protein kinase (PubMed:24120661). Acetylates RPTOR in response to leucine, leading to activation of the mTORC1 complex (PubMed:30197302, PubMed:32561715). Acetylates RICTOR, leading to activation of the mTORC2 complex (PubMed:22084251). Mediates cAMP-gene regulation by binding specifically to phosphorylated CREBBP (PubMed:8917528). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), butanoyl-CoA (butyryl-CoA), 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), lactoyl-CoA, propanoyl-CoA (propionyl-CoA) or isonicotinyl-CoA, and is able to mediate protein crotonylation, butyrylation, 2-hydroxyisobutyrylation, lactylation, propionylation or isonicotinylation, respectively (PubMed:17267393, PubMed:25818647, PubMed:29775581, PubMed:31645732, PubMed:34545082). Acts as a histone crotonyltransferase; crotonylation marks active promoters and enhancers and confers resistance to transcriptional repressors (PubMed:25818647). Histone crotonyltransferase activity is dependent on the concentration of (2E)-butenoyl-CoA (crotonyl-CoA) substrate and such activity is weak when (2E)-butenoyl-CoA (crotonyl-CoA) concentration is low (PubMed:25818647). Also acts as a histone butyryltransferase; butyrylation marks active promoters (PubMed:17267393). Catalyzes histone lactylation in macrophages by using lactoyl-CoA directly derived from endogenous or exogenous lactate, leading to stimulates gene transcription (PubMed:31645732). Acts as a protein-lysine 2-hydroxyisobutyryltransferase; regulates glycolysis by mediating 2-hydroxyisobutyrylation of glycolytic enzymes (PubMed:29775581). Functions as a transcriptional coactivator for SMAD4 in the TGF-beta signaling pathway (PubMed:25514493)\n(Microbial infection) In case of HIV-1 infection, it is recruited by the viral protein Tat. Regulates Tat's transactivating activity and may help inducing chromatin remodeling of proviral genes. Binds to and may be involved in the transforming capacity of the adenovirus E1A protein","source":"project UniProt records20261017/18"},{"partner":"NFYC","hgnc":"HGNC:7806","core":true,"core_annotation":{"hgnc":"HGNC:7806","symbol_at_source":"NFYC","accession":"Q13952","function":"Histone modification","target":"histone","pmids":["21445285"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":127,"hub_weight":0.5314940034527339,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the sequence-specific heterotrimeric transcription factor (NF-Y) which specifically recognizes a 5'-CCAAT-3' box motif found in the promoters of its target genes. NF-Y can function as both an activator and a repressor, depending on its interacting cofactors","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"DUX3":{"coreEvidence":[{"partner":"PRKCD","hgnc":"HGNC:9399","core":true,"core_annotation":{"hgnc":"HGNC:9399","symbol_at_source":"PRKCD","accession":"Q05655","function":"Histone modification","target":"histone","pmids":["17984964"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":113,"hub_weight":0.5538487756217113,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Cytoplasm, perinuclear region; Nucleus; Cell membrane; Mitochondrion; Endomembrane system","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Calcium-independent, phospholipid- and diacylglycerol (DAG)-dependent serine/threonine-protein kinase that plays contrasting roles in cell death and cell survival by functioning as a pro-apoptotic protein during DNA damage-induced apoptosis, but acting as an anti-apoptotic protein during cytokine receptor-initiated cell death, is involved in tumor suppression as well as survival of several cancers, is required for oxygen radical production by NADPH oxidase and acts as positive or negative regulator in platelet functional responses (PubMed:21406692, PubMed:21810427). Negatively regulates B cell proliferation and also has an important function in self-antigen induced B cell tolerance induction (By similarity). Upon DNA damage, activates the promoter of the death-promoting transcription factor BCLAF1/Btf to trigger BCLAF1-mediated p53/TP53 gene transcription and apoptosis (PubMed:21406692, PubMed:21810427). In response to oxidative stress, interact with and activate CHUK/IKKA in the nucleus, causing the phosphorylation of p53/TP53 (PubMed:21406692, PubMed:21810427). In the case of ER stress or DNA damage-induced apoptosis, can form a complex with the tyrosine-protein kinase ABL1 which trigger apoptosis independently of p53/TP53 (PubMed:21406692, PubMed:21810427). In cytosol can trigger apoptosis by activating MAPK11 or MAPK14, inhibiting AKT1 and decreasing the level of X-linked inhibitor of apoptosis protein (XIAP), whereas in nucleus induces apoptosis via the activation of MAPK8 or MAPK9. Upon ionizing radiation treatment, is required for the activation of the apoptosis regulators BAX and BAK, which trigger the mitochondrial cell death pathway. Can phosphorylate MCL1 and target it for degradation which is sufficient to trigger for BAX activation and apoptosis. Is required for the control of cell cycle progression both at G1/S and G2/M phases. Mediates phorbol 12-myristate 13-acetate (PMA)-induced inhibition of cell cycle progression at G1/S phase by up-regulating the CDK inhibitor CDKN1A/p21 and inhibiting the cyclin CCNA2 promoter activity. In response to UV irradiation can phosphorylate CDK1, which is important for the G2/M DNA damage checkpoint activation (By similarity). Can protect glioma cells from the apoptosis induced by TNFSF10/TRAIL, probably by inducing increased phosphorylation and subsequent activation of AKT1 (PubMed:15774464). Is highly expressed in a number of cancer cells and promotes cell survival and resistance against chemotherapeutic drugs by inducing cyclin D1 (CCND1) and hyperphosphorylation of RB1, and via several pro-survival pathways, including NF-kappa-B, AKT1 and MAPK1/3 (ERK1/2). Involved in antifungal immunity by mediating phosphorylation and activation of CARD9 downstream of C-type lectin receptors activation, promoting interaction between CARD9 and BCL10, followed by activation of NF-kappa-B and MAP kinase p38 pathways (By similarity). Can also act as tumor suppressor upon mitogenic stimulation with PMA or TPA. In N-formyl-methionyl-leucyl-phenylalanine (fMLP)-treated cells, is required for NCF1 (p47-phox) phosphorylation and activation of NADPH oxidase activity, and regulates TNF-elicited superoxide anion production in neutrophils, by direct phosphorylation and activation of NCF1 or indirectly through MAPK1/3 (ERK1/2) signaling pathways (PubMed:19801500). May also play a role in the regulation of NADPH oxidase activity in eosinophil after stimulation with IL5, leukotriene B4 or PMA (PubMed:11748588). In collagen-induced platelet aggregation, acts a negative regulator of filopodia formation and actin polymerization by interacting with and negatively regulating VASP phosphorylation (PubMed:16940418). Downstream of PAR1, PAR4 and CD36/GP4 receptors, regulates differentially platelet dense granule secretion; acts as a positive regulator in PAR-mediated granule secretion, whereas it negatively regulates CD36/GP4-mediated granule release (PubMed:19587372). Phosphorylates MUC1 in the C-terminal and regulates the interaction between MUC1 and beta-catenin (PubMed:11877440). The catalytic subunit phosphorylates 14-3-3 proteins (YWHAB, YWHAZ and YWHAH) in a sphingosine-dependent fashion (By similarity). Phosphorylates ELAVL1 in response to angiotensin-2 treatment (PubMed:18285462). Phosphorylates mitochondrial phospholipid scramblase 3 (PLSCR3), resulting in increased cardiolipin expression on the mitochondrial outer membrane which facilitates apoptosis (PubMed:12649167). Phosphorylates SMPD1 which induces SMPD1 secretion (PubMed:17303575). Acts as a negative regulator of smoothened signaling by mediating phosphorylation of GLI1, preventing its localization to the nucleus (PubMed:19015273). Acts as a regulator of dopamine signaling by mediating constitutive phosphorylation of dopamine receptor DRD1, inhibiting G protein-coupled receptor signaling (PubMed:20969574)","source":"project UniProt records20261017/18"},{"partner":"RIOX2","hgnc":"HGNC:19441","core":true,"core_annotation":{"hgnc":"HGNC:19441","symbol_at_source":"MINA","accession":"Q8IUF8","function":"Histone modification erase","target":"histone","pmids":["19502796"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":96,"hub_weight":0.5852057359806528,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Oxygenase that can act as both a histone lysine demethylase and a ribosomal histidine hydroxylase. Is involved in the demethylation of trimethylated 'Lys-9' on histone H3 (H3K9me3), leading to an increase in ribosomal RNA expression. Also catalyzes the hydroxylation of 60S ribosomal protein L27a on 'His-39'. May play an important role in cell growth and survival. May be involved in ribosome biogenesis, most likely during the assembly process of pre-ribosomal particles","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"DUX1","accession":"O43812","identity":0.976,"qcov":0.863,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":["9736770"],"function":"Probable transcription activator. Binds the P5 DNA element sequence 5'-GATCTGAGTCTAATTGAGAATTACTGTAC-3'","member_mechanism_evidence_available":true}]},"FAM149C":{"coreEvidence":[{"partner":"NAP1L1","hgnc":"HGNC:7637","core":true,"core_annotation":{"hgnc":"HGNC:7637","symbol_at_source":"NAP1L1","accession":"P55209","function":"Histone chaperone","target":"histone","pmids":["18226242"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":308,"hub_weight":0.37371754637596794,"quality":0.65,"programmes":["pubmed:34349018"],"pmids":["34349018"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome; Melanosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone chaperone that plays a role in the nuclear import of H2A-H2B and nucleosome assembly (PubMed:20002496, PubMed:21211722, PubMed:26841755). Also participates in several important DNA repair mechanisms: greatly enhances ERCC6-mediated chromatin remodeling which is essential for transcription-coupled nucleotide excision DNA repair (PubMed:28369616). Also stimulates homologous recombination (HR) by RAD51 and RAD54 which is essential in mitotic DNA double strand break (DSB) repair (PubMed:24798879). Plays a key role in the regulation of embryonic neurogenesis (By similarity). Promotes the proliferation of neural progenitors and inhibits neuronal differentiation during cortical development (By similarity). Regulates neurogenesis via the modulation of RASSF10; regulates RASSF10 expression by promoting SETD1A-mediated H3K4 methylation at the RASSF10 promoter (By similarity)\n(Microbial infection) Positively regulates Epstein-Barr virus reactivation in epithelial cells through the induction of viral BZLF1 expression\n(Microbial infection) Together with human herpesvirus 8 protein LANA1, assists the proper assembly of the nucleosome on the replicated viral DNA","source":"project UniProt records20261017/18"},{"partner":"HDGFL2","hgnc":"HGNC:14680","core":true,"core_annotation":{"hgnc":"HGNC:14680","symbol_at_source":"HDGFL2","accession":"Q7Z4V5","function":"Histone modification read","target":"histone","pmids":["217205545"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":179,"hub_weight":0.46726931351599776,"quality":0.65,"programmes":["pubmed:34349018"],"pmids":["34349018"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as an epigenetic regulator of myogenesis in cooperation with DPF3a (isoform 2 of DPF3/BAF45C) (PubMed:32459350). Associates with the BAF complex via its interaction with DPF3a and HDGFL2-DPF3a activate myogenic genes by increasing chromatin accessibility through recruitment of SMARCA4/BRG1/BAF190A (ATPase subunit of the BAF complex) to myogenic gene promoters (PubMed:32459350). Promotes the repair of DNA double-strand breaks (DSBs) through the homologous recombination pathway by facilitating the recruitment of the DNA endonuclease RBBP8 to the DSBs (PubMed:26721387). Preferentially binds to chromatin regions marked by H3K9me3, H3K27me3 and H3K36me2 (PubMed:26721387, PubMed:32459350). Involved in cellular growth control, through the regulation of cyclin D1 expression (PubMed:25689719)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"POTEJ":{"coreEvidence":[{"partner":"ACTB","hgnc":"HGNC:132","core":true,"core_annotation":{"hgnc":"HGNC:132","symbol_at_source":"ACTB","accession":"P60709","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["10966108"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, NuA4, NuA4-related complex","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":706,"hub_weight":0.25717224993681986,"quality":0.65,"programmes":["pubmed:34349018","pubmed:35575683"],"pmids":["34349018","35575683"],"assays":["crosslink"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Actin is a highly conserved protein that polymerizes to produce filaments that form cross-linked networks in the cytoplasm of cells (PubMed:25255767, PubMed:29581253). Actin exists in both monomeric (G-actin) and polymeric (F-actin) forms, both forms playing key functions, such as cell motility and contraction (PubMed:29581253). In addition to their role in the cytoplasmic cytoskeleton, G- and F-actin also localize in the nucleus, and regulate gene transcription and motility and repair of damaged DNA (PubMed:29925947). Plays a role in the assembly of the gamma-tubulin ring complex (gTuRC), which regulates the minus-end nucleation of alpha-beta tubulin heterodimers that grow into microtubule protafilaments (PubMed:39321809, PubMed:38609661). Part of the ACTR1A/ACTB filament around which the dynactin complex is built (By similarity). The dynactin multiprotein complex activates the molecular motor dynein for ultra-processive transport along microtubules (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CTBP1","hgnc":"HGNC:2494","core":true,"core_annotation":{"hgnc":"HGNC:2494","symbol_at_source":"CTBP1","accession":"Q13363","function":"Chromatin remodeling","target":"chromatin","pmids":["21102443"],"complexes":"LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":575,"hub_weight":0.282842712474619,"quality":0.65,"programmes":["pubmed:31041561"],"pmids":["31041561"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U-373 MG glioblastoma astrocytoma cell\", \"human-u373_mg\"]"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Corepressor targeting diverse transcription regulators such as GLIS2 or BCL6. Has dehydrogenase activity. Involved in controlling the equilibrium between tubular and stacked structures in the Golgi complex. Functions in brown adipose tissue (BAT) differentiation","source":"project UniProt records20261017/18"},{"partner":"AURKB","hgnc":"HGNC:11390","core":true,"core_annotation":{"hgnc":"HGNC:11390","symbol_at_source":"AURKB","accession":"Q96GD4","function":"Histone modification write","target":"histone","pmids":["11856369"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":583,"hub_weight":0.28104971365967135,"quality":0.65,"programmes":["pubmed:31586073"],"pmids":["31586073"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle; Midbody","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase component of the chromosomal passenger complex (CPC), a complex that acts as a key regulator of mitosis (PubMed:11516652, PubMed:12925766, PubMed:14610074, PubMed:14722118, PubMed:29449677). The CPC complex has essential functions at the centromere in ensuring correct chromosome alignment and segregation and is required for chromatin-induced microtubule stabilization and spindle assembly (PubMed:11516652, PubMed:12925766, PubMed:14610074, PubMed:14722118, PubMed:26829474). Involved in the bipolar attachment of spindle microtubules to kinetochores and is a key regulator for the onset of cytokinesis during mitosis (PubMed:15249581). Required for central/midzone spindle assembly and cleavage furrow formation (PubMed:12458200, PubMed:12686604). Key component of the cytokinesis checkpoint, a process required to delay abscission to prevent both premature resolution of intercellular chromosome bridges and accumulation of DNA damage: phosphorylates CHMP4C, leading to retain abscission-competent VPS4 (VPS4A and/or VPS4B) at the midbody ring until abscission checkpoint signaling is terminated at late cytokinesis (PubMed:22422861, PubMed:24814515). AURKB phosphorylates the CPC complex subunits BIRC5/survivin, CDCA8/borealin and INCENP (PubMed:11516652, PubMed:12925766, PubMed:14610074). Phosphorylation of INCENP leads to increased AURKB activity (PubMed:11516652, PubMed:12925766, PubMed:14610074). Other known AURKB substrates involved in centromeric functions and mitosis are CENPA, DES/desmin, GPAF, KIF2C, NSUN2, RACGAP1, SEPTIN1, VIM/vimentin, HASPIN, and histones H1.4 and H3 (PubMed:11756469, PubMed:11784863, PubMed:11856369, PubMed:12689593, PubMed:14602875, PubMed:16103226, PubMed:21511733, PubMed:21658950). A positive feedback loop involving HASPIN and AURKB contributes to localization of CPC to centromeres (PubMed:21658950). Phosphorylation of VIM controls vimentin filament segregation in cytokinetic process, whereas histone H3 is phosphorylated at 'Ser-10' and 'Ser-28' during mitosis (H3S10ph and H3S28ph, respectively) (PubMed:11784863, PubMed:11856369). AURKB is also required for kinetochore localization of BUB1 and SGO1 (PubMed:15020684, PubMed:17617734). Phosphorylation of p53/TP53 negatively regulates its transcriptional activity (PubMed:20959462). Key regulator of active promoters in resting B- and T-lymphocytes: acts by mediating phosphorylation of H3S28ph at active promoters in resting B-cells, inhibiting RNF2/RING1B-mediated ubiquitination of histone H2A and enhancing binding and activity of the USP16 deubiquitinase at transcribed genes (By similarity). Acts as an inhibitor of CGAS during mitosis: catalyzes phosphorylation of the N-terminus of CGAS during the G2-M transition, blocking CGAS liquid phase separation and activation, and thereby preventing CGAS-induced autoimmunity (PubMed:33542149). Phosphorylates KRT5 during anaphase and telophase (By similarity). Phosphorylates ATXN10 which promotes phosphorylation of ATXN10 by PLK1 and may play a role in the regulation of cytokinesis and stimulating the proteasomal degradation of ATXN10 (PubMed:25666058)","source":"project UniProt records20261017/18"},{"partner":"STK4","hgnc":"HGNC:11408","core":true,"core_annotation":{"hgnc":"HGNC:11408","symbol_at_source":"STK4","accession":"Q13043","function":"Histone modification write","target":"histone","pmids":["12757711"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":833,"hub_weight":0.23796037813647444,"quality":0.65,"programmes":["pubmed:39664081"],"pmids":["39664081"],"assays":["capture_association","proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Stress-activated, pro-apoptotic kinase which, following caspase-cleavage, enters the nucleus and induces chromatin condensation followed by internucleosomal DNA fragmentation. Key component of the Hippo signaling pathway which plays a pivotal role in organ size control and tumor suppression by restricting proliferation and promoting apoptosis. The core of this pathway is composed of a kinase cascade wherein STK3/MST2 and STK4/MST1, in complex with its regulatory protein SAV1, phosphorylates and activates LATS1/2 in complex with its regulatory protein MOB1, which in turn phosphorylates and inactivates YAP1 oncoprotein and WWTR1/TAZ. Phosphorylation of YAP1 by LATS2 inhibits its translocation into the nucleus to regulate cellular genes important for cell proliferation, cell death, and cell migration. STK3/MST2 and STK4/MST1 are required to repress proliferation of mature hepatocytes, to prevent activation of facultative adult liver stem cells (oval cells), and to inhibit tumor formation (By similarity). Phosphorylates 'Ser-14' of histone H2B (H2BS14ph) during apoptosis. Phosphorylates FOXO3 upon oxidative stress, which results in its nuclear translocation and cell death initiation. Phosphorylates MOBKL1A, MOBKL1B and RASSF2. Phosphorylates TNNI3 (cardiac Tn-I) and alters its binding affinity to TNNC1 (cardiac Tn-C) and TNNT2 (cardiac Tn-T). Phosphorylates FOXO1 on 'Ser-212' and regulates its activation and stimulates transcription of PMAIP1 in a FOXO1-dependent manner. Phosphorylates SIRT1 and inhibits SIRT1-mediated p53/TP53 deacetylation, thereby promoting p53/TP53 dependent transcription and apoptosis upon DNA damage. Acts as an inhibitor of PKB/AKT1. Phosphorylates AR on 'Ser-650' and suppresses its activity by intersecting with PKB/AKT1 signaling and antagonizing formation of AR-chromatin complexes","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"POTEF","accession":"A5A3E0","identity":0.935,"qcov":0.999,"tcov":0.999,"domain_context":"reference_Pfam_not_scanned_in_current_scope","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false},{"symbol":"POTEE","accession":"Q6S8J3","identity":0.935,"qcov":1.0,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"NXPE2":{"coreEvidence":[{"partner":"HELLS","hgnc":"HGNC:4861","core":true,"core_annotation":{"hgnc":"HGNC:4861","symbol_at_source":"HELLS","accession":"Q9NRZ9","function":"Chromatin remodeling","target":"chromatin","pmids":["14612388"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":157,"hub_weight":0.49147318718299043,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin remodeler that regulates chromatin accessibility, DNA methylation, and histone modifications. It facilitates de novo DNA methylation at repetitive sequences and promotes transcriptional silencing via recruitment of DNA methyltransferases (DNMTs) and histone deacetylases (HDACs), contributing to heterochromatin formation and repression of transposable elements (PubMed:30307408). Also involved in DNA repair by recruiting DNA damage response mediators to double-strand breaks in heterochromatin, promoting homologous recombination via RBBP8/CtIP-dependent end resection (PubMed:22946062, PubMed:31802118). During meiosis, it is recruited by PRDM9 to recombination hotspots, aiding chromatin opening (PubMed:32001511). Through these diverse roles, is crucial for processes such as development, differentiation, and genomic stability (PubMed:22946062, PubMed:31802118). Involved in regulation of the expansion or survival of lymphoid cells (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TRIM51":{"coreEvidence":[{"partner":"CDK7","hgnc":"HGNC:1778","core":true,"core_annotation":{"hgnc":"HGNC:1778","symbol_at_source":"CDK7","accession":"P50613","function":"Histone modification write","target":"histone","pmids":["10722743"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":348,"hub_weight":0.3544406025041679,"quality":0.65,"programmes":["pubmed:36042349"],"pmids":["36042349"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Cytoplasm, perinuclear region","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine kinase involved in cell cycle control and in RNA polymerase II-mediated RNA transcription (PubMed:9852112, PubMed:19136461, PubMed:26257281, PubMed:28768201). As a cyclin-dependent kinase, CDK7 is activated by the binding to cyclin-H/CCNH and the CDK-activating kinase assembly factor MAT1 (PubMed:41100585). Catalytic subunit of the CDK-activating kinase (CAK) complex, a master regulator of CDK activity by catalyzing the activating threonine phosphorylation of CDKs (PubMed:41100585). CAK activates major mediators of cell cycle control, including CDK1, CDK2, CDK4 and CDK6, and plays a key role in regulating cell cycle progression (PubMed:41100585). CAK complexed to the core-TFIIH basal transcription factor activates RNA polymerase II by serine phosphorylation of the CTD of POLR2A, allowing its escape from the promoter and elongation of the transcripts (PubMed:9852112). Initiates transcription by RNA polymerase II by mediating phosphorylation of POLR2A at 'Ser-5' of the repetitive C-terminal domain (CTD) when POLR2A is in complex with DNA, promoting dissociation from DNA and initiation (PubMed:19136461, PubMed:26257281, PubMed:28768201). Phosphorylates SPT5/SUPT5H, SF1/NR5A1, POLR2A, p53/TP53, CDK1, CDK2, CDK4, CDK6 and CDK11B/CDK11 (PubMed:9372954, PubMed:9840937, PubMed:19136461, PubMed:26257281, PubMed:28768201, PubMed:41100585, PubMed:41100585). Its expression and activity are constant throughout the cell cycle. Upon DNA damage, triggers p53/TP53 activation by phosphorylation, but is inactivated in turn by p53/TP53; this feedback loop may lead to an arrest of the cell cycle and of the transcription, helping in cell recovery, or to apoptosis. Required for DNA-bound peptides-mediated transcription and cellular growth inhibition","source":"project UniProt records20261017/18"},{"partner":"RNF40","hgnc":"HGNC:16867","core":true,"core_annotation":{"hgnc":"HGNC:16867","symbol_at_source":"RNF40","accession":"O75150","function":"Histone modification write cofactor","target":"histone","pmids":["16307923"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":201,"hub_weight":0.4463218426774518,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["16189514"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the RNF20/40 E3 ubiquitin-protein ligase complex that mediates monoubiquitination of 'Lys-120' of histone H2B (H2BK120ub1). H2BK120ub1 gives a specific tag for epigenetic transcriptional activation and is also prerequisite for histone H3 'Lys-4' and 'Lys-79' methylation (H3K4me and H3K79me, respectively). It thereby plays a central role in histone code and gene regulation. The RNF20/40 complex forms a H2B ubiquitin ligase complex in cooperation with the E2 enzyme UBE2A or UBE2B; reports about the cooperation with UBE2E1/UBCH are contradictory. Required for transcriptional activation of Hox genes\n(Microbial infection) Promotes the human herpesvirus 8 (KSHV) lytic cycle by inducing the expression of lytic viral genes including the latency switch gene RTA/ORF50","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MAGEB10":{"coreEvidence":[{"partner":"H2AC11","hgnc":"HGNC:4737","core":true,"core_annotation":{"hgnc":"HGNC:4737","symbol_at_source":"HIST1H2AG","accession":"P0C0S8","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":204,"hub_weight":0.4436782547080569,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"H2AX","hgnc":"HGNC:4739","core":true,"core_annotation":{"hgnc":"HGNC:4739","symbol_at_source":"H2AFX","accession":"P16104","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":507,"hub_weight":0.29961075885598987,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. Required for checkpoint-mediated arrest of cell cycle progression in response to low doses of ionizing radiation and for efficient repair of DNA double strand breaks (DSBs) specifically when modified by C-terminal phosphorylation","source":"project UniProt records20261017/18"},{"partner":"MYBBP1A","hgnc":"HGNC:7546","core":true,"core_annotation":{"hgnc":"HGNC:7546","symbol_at_source":"MYBBP1A","accession":"Q9BQG0","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["16603771"],"complexes":"B-WICH","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":425,"hub_weight":0.3244428422615251,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May activate or repress transcription via interactions with sequence specific DNA-binding proteins (By similarity). Repression may be mediated at least in part by histone deacetylase activity (HDAC activity) (By similarity). Acts as a corepressor and in concert with CRY1, represses the transcription of the core circadian clock component PER2 (By similarity). Preferentially binds to dimethylated histone H3 'Lys-9' (H3K9me2) on the PER2 promoter (By similarity). Has a role in rRNA biogenesis together with PWP1 (PubMed:29065309)","source":"project UniProt records20261017/18"},{"partner":"NOC2L","hgnc":"HGNC:24517","core":true,"core_annotation":{"hgnc":"HGNC:24517","symbol_at_source":"NOC2L","accession":"Q9Y3T9","function":"Chromatin remodeling, TF","target":"histone","pmids":["15100215"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":262,"hub_weight":0.40032038451271784,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleoplasm; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as an inhibitor of histone acetyltransferase activity; prevents acetylation of all core histones by the EP300/p300 histone acetyltransferase at p53/TP53-regulated target promoters in a histone deacetylases (HDAC)-independent manner. Acts as a transcription corepressor of p53/TP53- and TP63-mediated transactivation of the p21/CDKN1A promoter. Involved in the regulation of p53/TP53-dependent apoptosis. Associates together with TP63 isoform TA*-gamma to the p21/CDKN1A promoter","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"MAGEB1","accession":"P43366","identity":0.524,"qcov":0.991,"tcov":0.991,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false},{"symbol":"MAGEB4","accession":"O15481","identity":0.53,"qcov":0.994,"tcov":0.994,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"FAM53C":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"USP21","hgnc":"HGNC:12620","core":true,"core_annotation":{"hgnc":"HGNC:12620","symbol_at_source":"USP21","accession":"Q9UK80","function":"Histone modification erase","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":120,"hub_weight":0.5423261445466404,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinates histone H2A, a specific tag for epigenetic transcriptional repression, thereby acting as a coactivator (By similarity). Deubiquitination of histone H2A releaves the repression of di- and trimethylation of histone H3 at 'Lys-4', resulting in regulation of transcriptional initiation (By similarity). Regulates gene expression via histone H2A deubiquitination (By similarity). Deubiquitinates BAZ2A/TIP5 leading to its stabilization (PubMed:26100909). Also capable of removing NEDD8 from NEDD8 conjugates but has no effect on Sentrin-1 conjugates (PubMed:10799498). Also acts as a negative regulator of the ribosome quality control (RQC) by mediating deubiquitination of 40S ribosomal proteins RPS10/eS10 and RPS20/uS10, thereby antagonizing ZNF598-mediated 40S ubiquitination (PubMed:32011234)","source":"project UniProt records20261017/18"},{"partner":"YWHAB","hgnc":"HGNC:12849","core":true,"core_annotation":{"hgnc":"HGNC:12849","symbol_at_source":"YWHAB","accession":"P31946","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":704,"hub_weight":0.2575131013123024,"quality":0.65,"programmes":["BioPlex","pubmed:35271311","pubmed:36931259","pubmed:40205054"],"pmids":["33961781","35271311","36931259","40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens HEK293flp-in embryonic kidney cell\", \"human-293flp-in\"]","IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Melanosome; Vacuole membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways. Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif. Binding generally results in the modulation of the activity of the binding partner. Negative regulator of osteogenesis. Blocks the nuclear translocation of the phosphorylated form (by AKT1) of SRPK2 and antagonizes its stimulatory effect on cyclin D1 expression resulting in blockage of neuronal apoptosis elicited by SRPK2. Negative regulator of signaling cascades that mediate activation of MAP kinases via AKAP13","source":"project UniProt records20261017/18"},{"partner":"YWHAE","hgnc":"HGNC:12851","core":true,"core_annotation":{"hgnc":"HGNC:12851","symbol_at_source":"YWHAE","accession":"P62258","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":833,"hub_weight":0.23796037813647444,"quality":0.75,"programmes":["CCSB_binary_maps","pubmed:17979178","pubmed:35271311","pubmed:36931259"],"pmids":["17979178","25416956","35271311","36931259"],"assays":["binary_reporter","capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens HEK293flp-in embryonic kidney cell\", \"human-293flp-in\"]"],"partner_location":"Nucleus; Cytoplasm; Melanosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:21189250). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35343654). Binding generally results in the modulation of the activity of the binding partner (By similarity). Positively regulates phosphorylated protein HSF1 nuclear export to the cytoplasm (PubMed:12917326). Plays a positive role in the antiviral signaling pathway upstream of TBK1 via interaction with RIGI (PubMed:37555661). Mechanistically, directs RIGI redistribution from the cytosol to mitochondrial associated membranes where it mediates MAVS-dependent innate immune signaling during viral infection (PubMed:22607805). Plays a role in proliferation inhibition and cell cycle arrest by exporting HNRNPC from the nucleus to the cytoplasm to be degraded by ubiquitination (PubMed:37599448)","source":"project UniProt records20261017/18"},{"partner":"YWHAZ","hgnc":"HGNC:12855","core":true,"core_annotation":{"hgnc":"HGNC:12855","symbol_at_source":"YWHAZ","accession":"P63104","function":"Histone modification read","target":"histone","pmids":["16246723"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":960,"hub_weight":0.2224970797449924,"quality":0.75,"programmes":["BioPlex","pubmed:20936779","pubmed:35271311","pubmed:36931259"],"pmids":["20936779","28514442","33961781","35271311","36931259"],"assays":["binary_reporter","capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens HEK293flp-in embryonic kidney cell\", \"human-293flp-in\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Melanosome","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:14578935, PubMed:15071501, PubMed:15644438, PubMed:16376338, PubMed:16959763, PubMed:31024343, PubMed:9360956). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35662396). Binding generally results in the modulation of the activity of the binding partner (PubMed:35662396). Promotes cytosolic retention and inactivation of TFEB transcription factor by binding to phosphorylated TFEB (PubMed:35662396). Induces ARHGEF7 activity on RAC1 as well as lamellipodia and membrane ruffle formation (PubMed:16959763). In neurons, regulates spine maturation through the modulation of ARHGEF7 activity (By similarity)","source":"project UniProt records20261017/18"},{"partner":"HDAC4","hgnc":"HGNC:14063","core":true,"core_annotation":{"hgnc":"HGNC:14063","symbol_at_source":"HDAC4","accession":"P56524","function":"Histone modification erase","target":"histone","pmids":["10220385"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":301,"hub_weight":0.3774256780481986,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Responsible for the deacetylation of lysine residues on the N-terminal part of the core histones (H2A, H2B, H3 and H4). Histone deacetylation gives a tag for epigenetic repression and plays an important role in transcriptional regulation, cell cycle progression and developmental events. Histone deacetylases act via the formation of large multiprotein complexes. Involved in muscle maturation via its interaction with the myocyte enhancer factors such as MEF2A, MEF2C and MEF2D. Involved in the MTA1-mediated epigenetic regulation of ESR1 expression in breast cancer. Deacetylates HSPA1A and HSPA1B at 'Lys-77' leading to their preferential binding to co-chaperone STUB1 (PubMed:27708256)","source":"project UniProt records20261017/18"},{"partner":"TRIM33","hgnc":"HGNC:16290","core":true,"core_annotation":{"hgnc":"HGNC:16290","symbol_at_source":"TRIM33","accession":"Q9UPN9","function":"Histone modification read","target":"histone","pmids":["23926104"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":373,"hub_weight":0.3438070820862645,"quality":0.65,"programmes":["pubmed:31753913"],"pmids":["31753913"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as an E3 ubiquitin-protein ligase. Promotes SMAD4 ubiquitination, nuclear exclusion and degradation via the ubiquitin proteasome pathway. According to PubMed:16751102, does not promote a decrease in the level of endogenous SMAD4. May act as a transcriptional repressor. Inhibits the transcriptional response to TGF-beta/BMP signaling cascade. Plays a role in the control of cell proliferation. Its association with SMAD2 and SMAD3 stimulates erythroid differentiation of hematopoietic stem/progenitor (By similarity). Monoubiquitinates SMAD4 and acts as an inhibitor of SMAD4-dependent TGF-beta/BMP signaling cascade (Monoubiquitination of SMAD4 hampers its ability to form a stable complex with activated SMAD2/3 resulting in inhibition of TGF-beta/BMP signaling cascade)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C20orf202":{"coreEvidence":[{"partner":"SGF29","hgnc":"HGNC:25156","core":true,"core_annotation":{"hgnc":"HGNC:25156","symbol_at_source":"CCDC101","accession":"Q96ES7","function":"Histone modification read","target":"histone","pmids":["21685874"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":129,"hub_weight":0.52851642258169,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader component of some histone acetyltransferase (HAT) SAGA-type complexes like the TFTC-HAT, ATAC or STAGA complexes (PubMed:19103755, PubMed:20850016, PubMed:21685874, PubMed:26421618, PubMed:26578293). SGF29 specifically recognizes and binds methylated 'Lys-4' of histone H3 (H3K4me), with a preference for trimethylated form (H3K4me3) (PubMed:20850016, PubMed:21685874, PubMed:26421618, PubMed:26578293). In the SAGA-type complexes, SGF29 is required to recruit complexes to H3K4me (PubMed:20850016). Involved in the response to endoplasmic reticulum (ER) stress by recruiting the SAGA complex to H3K4me, thereby promoting histone H3 acetylation and cell survival (PubMed:23894581). Also binds non-histone proteins that are methylated on Lys residues: specifically recognizes and binds CGAS monomethylated on 'Lys-506' (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"CAPSL":{"coreEvidence":[],"near_known_relatives":[]},"TMEM82":{"coreEvidence":[{"partner":"H2BC12L","hgnc":"HGNC:4762","core":true,"core_annotation":{"hgnc":"HGNC:4762","symbol_at_source":"H2BFS","accession":"P57053","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":225,"hub_weight":0.4264014327112209,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling\nHas broad antibacterial activity. May contribute to the formation of the functional antimicrobial barrier of the colonic epithelium, and to the bactericidal activity of amniotic fluid","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C6orf118":{"coreEvidence":[{"partner":"SGF29","hgnc":"HGNC:25156","core":true,"core_annotation":{"hgnc":"HGNC:25156","symbol_at_source":"CCDC101","accession":"Q96ES7","function":"Histone modification read","target":"histone","pmids":["21685874"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":129,"hub_weight":0.52851642258169,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader component of some histone acetyltransferase (HAT) SAGA-type complexes like the TFTC-HAT, ATAC or STAGA complexes (PubMed:19103755, PubMed:20850016, PubMed:21685874, PubMed:26421618, PubMed:26578293). SGF29 specifically recognizes and binds methylated 'Lys-4' of histone H3 (H3K4me), with a preference for trimethylated form (H3K4me3) (PubMed:20850016, PubMed:21685874, PubMed:26421618, PubMed:26578293). In the SAGA-type complexes, SGF29 is required to recruit complexes to H3K4me (PubMed:20850016). Involved in the response to endoplasmic reticulum (ER) stress by recruiting the SAGA complex to H3K4me, thereby promoting histone H3 acetylation and cell survival (PubMed:23894581). Also binds non-histone proteins that are methylated on Lys residues: specifically recognizes and binds CGAS monomethylated on 'Lys-506' (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TMEM51":{"coreEvidence":[],"near_known_relatives":[]},"MAGEE2":{"coreEvidence":[{"partner":"PCGF6","hgnc":"HGNC:21156","core":true,"core_annotation":{"hgnc":"HGNC:21156","symbol_at_source":"PCGF6","accession":"Q9BYE7","function":"Polycomb group (PcG) protein","target":"#","pmids":["21282530"],"complexes":"PRC1, RING2-L3MBTL2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":159,"hub_weight":0.4891159880445185,"quality":0.75,"programmes":["pubmed:25590999"],"pmids":["25590999"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional repressor (PubMed:12167161). May modulate the levels of histone H3K4Me3 by activating KDM5D histone demethylase (PubMed:17320162). Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility (PubMed:12167161). Within the PRC1-like complex, regulates RNF2 ubiquitin ligase activity (PubMed:26151332)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"GOLGA6A":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"PRKAA2","hgnc":"HGNC:9377","core":true,"core_annotation":{"hgnc":"HGNC:9377","symbol_at_source":"PRKAA2","accession":"P54646","function":"Histone modification write","target":"histone","pmids":["20647423"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":167,"hub_weight":0.4800153607373193,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Late endosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:17307971, PubMed:17712357). In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation (PubMed:17307971, PubMed:17712357). AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators (PubMed:17307971, PubMed:17712357). Regulates lipid synthesis by phosphorylating and inactivating lipid metabolic enzymes such as ACACA, ACACB, GYS1, HMGCR and LIPE; regulates fatty acid and cholesterol synthesis by phosphorylating acetyl-CoA carboxylase (ACACA and ACACB) and hormone-sensitive lipase (LIPE) enzymes, respectively (PubMed:7959015). Promotes lipolysis of lipid droplets by mediating phosphorylation of isoform 1 of CHKA (CHKalpha2) (PubMed:34077757). Regulates insulin-signaling and glycolysis by phosphorylating IRS1, PFKFB2 and PFKFB3 (By similarity). Involved in insulin receptor/INSR internalization (PubMed:25687571). AMPK stimulates glucose uptake in muscle by increasing the translocation of the glucose transporter SLC2A4/GLUT4 to the plasma membrane, possibly by mediating phosphorylation of TBC1D4/AS160 (By similarity). Regulates transcription and chromatin structure by phosphorylating transcription regulators involved in energy metabolism such as CRTC2/TORC2, FOXO3, histone H2B, HDAC5, MEF2C, MLXIPL/ChREBP, EP300, HNF4A, p53/TP53, SREBF1, SREBF2 and PPARGC1A (PubMed:11518699, PubMed:11554766, PubMed:15866171, PubMed:17711846, PubMed:18184930). Acts as a key regulator of glucose homeostasis in liver by phosphorylating CRTC2/TORC2, leading to CRTC2/TORC2 sequestration in the cytoplasm (By similarity). In response to stress, phosphorylates 'Ser-36' of histone H2B (H2BS36ph), leading to promote transcription (By similarity). Acts as a key regulator of cell growth and proliferation by phosphorylating FNIP1, TSC2, RPTOR, WDR24 and ATG1/ULK1: in response to nutrient limitation, negatively regulates the mTORC1 complex by phosphorylating RPTOR component of the mTORC1 complex and by phosphorylating and activating TSC2 (PubMed:14651849, PubMed:20160076, PubMed:21205641). Also phosphorylates and inhibits GATOR2 subunit WDR24 in response to nutrient limitation, leading to suppress glucose-mediated mTORC1 activation (PubMed:36732624). In response to energetic stress, phosphorylates FNIP1, inactivating the non-canonical mTORC1 signaling, thereby promoting nuclear translocation of TFEB and TFE3, and inducing transcription of lysosomal or autophagy genes (PubMed:37079666). In response to nutrient limitation, promotes autophagy by phosphorylating and activating ATG1/ULK1 (PubMed:21205641). In that process, it also activates WDR45/WIPI4 (PubMed:28561066). Phosphorylates CASP6, thereby preventing its autoprocessing and subsequent activation (PubMed:32029622). AMPK also acts as a regulator of circadian rhythm by mediating phosphorylation of CRY1, leading to destabilize it (By similarity). May regulate the Wnt signaling pathway by phosphorylating CTNNB1, leading to stabilize it (By similarity). Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin (PubMed:17486097). Also phosphorylates CFTR, EEF2K, KLC1, NOS3 and SLC12A1 (PubMed:12519745, PubMed:20074060). Plays an important role in the differential regulation of pro-autophagy (composed of PIK3C3, BECN1, PIK3R4 and UVRAG or ATG14) and non-autophagy (composed of PIK3C3, BECN1 and PIK3R4) complexes, in response to glucose starvation (By similarity). Can inhibit the non-autophagy complex by phosphorylating PIK3C3 and can activate the pro-autophagy complex by phosphorylating BECN1 (By similarity). Upon glucose starvation, promotes ARF6 activation in a kinase-independent manner leading to cell migration (PubMed:36017701). Upon glucose deprivation mediates the phosphorylation of ACSS2 at 'Ser-659', which exposes the nuclear localization signal of ACSS2, required for its interaction with KPNA1 and nuclear translocation (PubMed:28552616). Upon stress, regulates mitochondrial fragmentation through phosphorylation of MTFR1L (PubMed:36367943)","source":"project UniProt records20261017/18"},{"partner":"USP15","hgnc":"HGNC:12613","core":true,"core_annotation":{"hgnc":"HGNC:12613","symbol_at_source":"USP15","accession":"Q9Y4E8","function":"Histone modification erase","target":"histone","pmids":["24526689"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":362,"hub_weight":0.34836650714580886,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Hydrolase that removes conjugated ubiquitin from target proteins and regulates various pathways such as the TGF-beta receptor signaling, NF-kappa-B and RNF41/NRDP1-PRKN pathways (PubMed:16005295, PubMed:17318178, PubMed:19576224, PubMed:19826004, PubMed:21947082, PubMed:22344298, PubMed:24852371). Acts as a key regulator of TGF-beta receptor signaling pathway, but the precise mechanism is still unclear: according to a report, acts by promoting deubiquitination of monoubiquitinated R-SMADs (SMAD1, SMAD2 and/or SMAD3), thereby alleviating inhibition of R-SMADs and promoting activation of TGF-beta target genes (PubMed:21947082). According to another reports, regulates the TGF-beta receptor signaling pathway by mediating deubiquitination and stabilization of TGFBR1, leading to an enhanced TGF-beta signal (PubMed:22344298). Able to mediate deubiquitination of monoubiquitinated substrates, 'Lys-27'-, 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains (PubMed:33093067). May also regulate gene expression and/or DNA repair through the deubiquitination of histone H2B (PubMed:24526689). Acts as an inhibitor of mitophagy by counteracting the action of parkin (PRKN): hydrolyzes cleavage of 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains attached by parkin on target proteins such as MFN2, thereby reducing parkin's ability to drive mitophagy (PubMed:24852371). Acts as an associated component of COP9 signalosome complex (CSN) and regulates different pathways via this association: regulates NF-kappa-B by mediating deubiquitination of NFKBIA and deubiquitinates substrates bound to VCP (PubMed:16005295, PubMed:17318178, PubMed:19576224, PubMed:19826004). Involved in endosome organization by mediating deubiquitination of SQSTM1: ubiquitinated SQSTM1 forms a molecular bridge that restrains cognate vesicles in the perinuclear region and its deubiquitination releases target vesicles for fast transport into the cell periphery (PubMed:27368102). Acts as a negative regulator of antifungal immunity by mediating 'Lys-27'-linked deubiquitination of CARD9, thereby inactivating CARD9 (PubMed:33093067)\n(Microbial infection) Protects APC and human papillomavirus type 16 protein E6 against degradation via the ubiquitin proteasome pathway","source":"project UniProt records20261017/18"},{"partner":"MORF4L1","hgnc":"HGNC:16989","core":true,"core_annotation":{"hgnc":"HGNC:16989","symbol_at_source":"MORF4L1","accession":"Q9UBU8","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"NuA4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":199,"hub_weight":0.4481107149482208,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the NuA4 histone acetyltransferase (HAT) complex which is involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H4 and H2A. This modification may both alter nucleosome - DNA interactions and promote interaction of the modified histones with other proteins which positively regulate transcription. This complex may be required for the activation of transcriptional programs associated with oncogene and proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair. The NuA4 complex ATPase and helicase activities seem to be, at least in part, contributed by the association of RUVBL1 and RUVBL2 with EP400. NuA4 may also play a direct role in DNA repair when directly recruited to sites of DNA damage. As part of the SIN3B complex represses transcription and counteracts the histone acetyltransferase activity of EP300 through the recognition H3K27ac marks by PHF12 and the activity of the histone deacetylase HDAC2 (PubMed:12391155, PubMed:14966270, PubMed:37137925). SIN3B complex is recruited downstream of the constitutively active genes transcriptional start sites through interaction with histones and mitigates histone acetylation and RNA polymerase II progression within transcribed regions contributing to the regulation of transcription (PubMed:21041482). Required for homologous recombination repair (HRR) and resistance to mitomycin C (MMC). Involved in the localization of PALB2, BRCA2 and RAD51, but not BRCA1, to DNA-damage foci","source":"project UniProt records20261017/18"},{"partner":"KDM1A","hgnc":"HGNC:29079","core":true,"core_annotation":{"hgnc":"HGNC:29079","symbol_at_source":"KDM1A","accession":"O60341","function":"Histone modification erase","target":"histone","pmids":["16223729"],"complexes":"NuRD, BHC, SCL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":641,"hub_weight":0.26899609689495085,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that can demethylate both 'Lys-4' (H3K4me) and 'Lys-9' (H3K9me) of histone H3, thereby acting as a coactivator or a corepressor, depending on the context (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:16079795, PubMed:16140033, PubMed:16223729, PubMed:27292636). Acts by oxidizing the substrate by FAD to generate the corresponding imine that is subsequently hydrolyzed (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:21300290, PubMed:26214369). Acts as a corepressor by mediating demethylation of H3K4me, a specific tag for epigenetic transcriptional activation. Demethylates both mono- (H3K4me1) and di-methylated (H3K4me2) (PubMed:15620353, PubMed:20389281, PubMed:21300290, PubMed:23721412). May play a role in the repression of neuronal genes. Alone, it is unable to demethylate H3K4me on nucleosomes and requires the presence of RCOR1/CoREST to achieve such activity (PubMed:16079794, PubMed:16140033, PubMed:16885027, PubMed:21300290, PubMed:23721412). Also acts as a coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and mediating demethylation of H3K9me, a specific tag for epigenetic transcriptional repression. The presence of PRKCB in AR-containing complexes, which mediates phosphorylation of 'Thr-6' of histone H3 (H3T6ph), a specific tag that prevents demethylation H3K4me, prevents H3K4me demethylase activity of KDM1A (PubMed:16079795). Demethylates di-methylated 'Lys-370' of p53/TP53 which prevents interaction of p53/TP53 with TP53BP1 and represses p53/TP53-mediated transcriptional activation. Demethylates and stabilizes the DNA methylase DNMT1 (PubMed:29691401). Demethylates methylated 'Lys-42' and methylated 'Lys-117' of SOX2 (PubMed:29358331). Required for gastrulation during embryogenesis. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (PubMed:16079794, PubMed:16140033). Facilitates epithelial-to-mesenchymal transition by acting as an effector of SNAI1-mediated transcription repression of epithelial markers E-cadherin/CDH1, CDN7 and KRT8 (PubMed:20562920, PubMed:27292636). Required for the maintenance of the silenced state of the SNAI1 target genes E-cadherin/CDH1 and CDN7 (PubMed:20389281). Required for the repression of GIPR expression (PubMed:34655521, PubMed:34906447)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MAGEB3":{"coreEvidence":[{"partner":"ATAD2","hgnc":"HGNC:30123","core":true,"core_annotation":{"hgnc":"HGNC:30123","symbol_at_source":"ATAD2","accession":"Q6PL18","function":"Chromatin remodeling","target":"chromatin","pmids":["17998543"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":62,"hub_weight":0.6681531047810609,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May be a transcriptional coactivator of the nuclear receptor ESR1 required to induce the expression of a subset of estradiol target genes, such as CCND1, MYC and E2F1. May play a role in the recruitment or occupancy of CREBBP at some ESR1 target gene promoters. May be required for histone hyperacetylation. Involved in the estrogen-induced cell proliferation and cell cycle progression of breast cancer cells","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"MAGEB2","accession":"O15479","identity":0.509,"qcov":0.91,"tcov":0.987,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":["20864041"],"function":"May enhance ubiquitin ligase activity of RING-type zinc finger-containing E3 ubiquitin-protein ligases. Proposed to act through recruitment and/or stabilization of the Ubl-conjugating enzyme (E2) at the E3:substrate complex","member_mechanism_evidence_available":true},{"symbol":"MAGEB1","accession":"P43366","identity":0.528,"qcov":0.922,"tcov":0.911,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false},{"symbol":"MAGEB4","accession":"O15481","identity":0.556,"qcov":0.994,"tcov":0.991,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"WDR88":{"coreEvidence":[],"near_known_relatives":[]},"DCAF4L2":{"coreEvidence":[{"partner":"CUL4A","hgnc":"HGNC:2554","core":true,"core_annotation":{"hgnc":"HGNC:2554","symbol_at_source":"CUL4A","accession":"Q13619","function":"Histone modification write","target":"histone","pmids":["16678110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":588,"hub_weight":0.2799462554779272,"quality":0.65,"programmes":["BioPlex","pubmed:27158335"],"pmids":["26186194","27158335","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Core component of multiple cullin-RING-based E3 ubiquitin-protein ligase complexes which mediate the ubiquitination of target proteins (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620, PubMed:30166453, PubMed:33854232, PubMed:33854239). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1 (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). The functional specificity of the E3 ubiquitin-protein ligase complex depends on the variable substrate recognition component (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). DCX(DET1-COP1) directs ubiquitination of JUN (PubMed:14739464). DCX(DDB2) directs ubiquitination of XPC (PubMed:15811626). DCX(DDB2) ubiquitinates histones H3-H4 and is required for efficient histone deposition during replication-coupled (H3.1) and replication-independent (H3.3) nucleosome assembly, probably by facilitating the transfer of H3 from ASF1A/ASF1B to other chaperones involved in histone deposition (PubMed:16678110, PubMed:17041588, PubMed:24209620). DCX(DTL) plays a role in PCNA-dependent polyubiquitination of CDT1 and MDM2-dependent ubiquitination of p53/TP53 in response to radiation-induced DNA damage and during DNA replication (PubMed:14578910, PubMed:15448697, PubMed:15548678). DCX(DTL) directs autoubiquitination of DTL (PubMed:23478445). In association with DDB1 and SKP2 probably is involved in ubiquitination of CDKN1B/p27kip (PubMed:16537899). Is involved in ubiquitination of HOXA9 (PubMed:14609952). The DDB1-CUL4A-DTL E3 ligase complex regulates the circadian clock function by mediating the ubiquitination and degradation of CRY1 (PubMed:26431207). The DCX(ERCC8) complex (also named CSA complex) plays a role in transcription-coupled repair (TCR) (PubMed:12732143, PubMed:32355176, PubMed:38316879). A number of DCX complexes (containing either TRPC4AP or DCAF12 as substrate-recognition component) are part of the DesCEND (destruction via C-end degrons) pathway, which recognizes a C-degron located at the extreme C terminus of target proteins, leading to their ubiquitination and degradation (PubMed:29779948). The DCX(AMBRA1) complex is a master regulator of the transition from G1 to S cell phase by mediating ubiquitination of phosphorylated cyclin-D (CCND1, CCND2 and CCND3) (PubMed:33854232, PubMed:33854239). The DCX(AMBRA1) complex also acts as a regulator of Cul5-RING (CRL5) E3 ubiquitin-protein ligase complexes by mediating ubiquitination and degradation of Elongin-C (ELOC) component of CRL5 complexes (PubMed:30166453). With CUL4B, contributes to ribosome biogenesis (PubMed:26711351)","source":"project UniProt records20261017/18"},{"partner":"CUL4B","hgnc":"HGNC:2555","core":true,"core_annotation":{"hgnc":"HGNC:2555","symbol_at_source":"CUL4B","accession":"Q13620","function":"Histone modification write","target":"histone","pmids":["16678110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":579,"hub_weight":0.2819419372173005,"quality":0.65,"programmes":["BioPlex","pubmed:27158335"],"pmids":["26186194","27158335","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:14578910, PubMed:16322693, PubMed:16678110, PubMed:18593899, PubMed:22118460, PubMed:29779948, PubMed:30166453, PubMed:33854232, PubMed:33854239, PubMed:25970626). The functional specificity of the E3 ubiquitin-protein ligase complex depends on the variable substrate recognition subunit (PubMed:14578910, PubMed:16678110, PubMed:18593899, PubMed:22118460, PubMed:29779948). CUL4B may act within the complex as a scaffold protein, contributing to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme (PubMed:14578910, PubMed:16678110, PubMed:18593899, PubMed:22118460). Plays a role as part of the E3 ubiquitin-protein ligase complex in polyubiquitination of CDT1, histone H2A, histone H3 and histone H4 in response to radiation-induced DNA damage (PubMed:14578910, PubMed:16678110, PubMed:18593899). Targeted to UV damaged chromatin by DDB2 and may be important for DNA repair and DNA replication (PubMed:16678110). A number of DCX complexes (containing either TRPC4AP or DCAF12 as substrate-recognition component) are part of the DesCEND (destruction via C-end degrons) pathway, which recognizes a C-degron located at the extreme C terminus of target proteins, leading to their ubiquitination and degradation (PubMed:29779948). The DCX(AMBRA1) complex is a master regulator of the transition from G1 to S cell phase by mediating ubiquitination of phosphorylated cyclin-D (CCND1, CCND2 and CCND3) (PubMed:33854232, PubMed:33854239). The DCX(AMBRA1) complex also acts as a regulator of Cul5-RING (CRL5) E3 ubiquitin-protein ligase complexes by mediating ubiquitination and degradation of Elongin-C (ELOC) component of CRL5 complexes (PubMed:30166453). Required for ubiquitination of cyclin E (CCNE1 or CCNE2), and consequently, normal G1 cell cycle progression (PubMed:16322693, PubMed:19801544). Regulates the mammalian target-of-rapamycin (mTOR) pathway involved in control of cell growth, size and metabolism (PubMed:18235224). Specific CUL4B regulation of the mTORC1-mediated pathway is dependent upon 26S proteasome function and requires interaction between CUL4B and MLST8 (PubMed:18235224). With CUL4A, contributes to ribosome biogenesis (PubMed:26711351)","source":"project UniProt records20261017/18"},{"partner":"DDB1","hgnc":"HGNC:2717","core":true,"core_annotation":{"hgnc":"HGNC:2717","symbol_at_source":"DDB1","accession":"Q16531","function":"Histone modification write","target":"histone","pmids":["16678110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":604,"hub_weight":0.2765006318046655,"quality":0.65,"programmes":["BioPlex","pubmed:27158335"],"pmids":["27158335","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in DNA repair and protein ubiquitination, as part of the UV-DDB complex and DCX (DDB1-CUL4-X-box) complexes, respectively (PubMed:14739464, PubMed:15448697, PubMed:16260596, PubMed:16407242, PubMed:16407252, PubMed:16482215, PubMed:16940174, PubMed:17079684, PubMed:25970626). Core component of the UV-DDB complex (UV-damaged DNA-binding protein complex), a complex that recognizes UV-induced DNA damage and recruits proteins of the nucleotide excision repair pathway (the NER pathway) to initiate DNA repair (PubMed:15448697, PubMed:16260596, PubMed:16407242, PubMed:16940174). The UV-DDB complex preferentially binds to cyclobutane pyrimidine dimers (CPD), 6-4 photoproducts (6-4 PP), apurinic sites and short mismatches (PubMed:15448697, PubMed:16260596, PubMed:16407242, PubMed:16940174). Component of numerous distinct DCX (DDB1-CUL4-X-box) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:14739464, PubMed:16407252, PubMed:16482215, PubMed:17079684, PubMed:18332868, PubMed:18381890, PubMed:19966799, PubMed:22118460, PubMed:25043012, PubMed:25108355, PubMed:28886238, PubMed:41565821). The functional specificity of the DCX E3 ubiquitin-protein ligase complex is determined by the variable substrate recognition component recruited by DDB1 (PubMed:14739464, PubMed:16407252, PubMed:16482215, PubMed:17079684, PubMed:18332868, PubMed:18381890, PubMed:19966799, PubMed:22118460, PubMed:25043012, PubMed:25108355). DCX(DDB2) (also known as DDB1-CUL4-ROC1, CUL4-DDB-ROC1 and CUL4-DDB-RBX1) may ubiquitinate histone H2A, histone H3 and histone H4 at sites of UV-induced DNA damage (PubMed:16473935, PubMed:16678110, PubMed:17041588, PubMed:18593899). The ubiquitination of histones may facilitate their removal from the nucleosome and promote subsequent DNA repair (PubMed:16473935, PubMed:16678110, PubMed:17041588, PubMed:18593899). DCX(DDB2) also ubiquitinates XPC, which may enhance DNA-binding by XPC and promote NER (PubMed:15882621). DCX(DTL) plays a role in PCNA-dependent polyubiquitination of CDT1 and MDM2-dependent ubiquitination of TP53 in response to radiation-induced DNA damage and during DNA replication (PubMed:17041588). DCX(ERCC8) (the CSA complex) plays a role in transcription-coupled repair (TCR) (PubMed:12732143, PubMed:32355176, PubMed:38316879). The DDB1-CUL4A-DTL E3 ligase complex regulates the circadian clock function by mediating the ubiquitination and degradation of CRY1 (PubMed:26431207). DDB1-mediated CRY1 degradation promotes FOXO1 protein stability and FOXO1-mediated gluconeogenesis in the liver (By similarity). By acting on TET dioxygenases, essential for oocyte maintenance at the primordial follicle stage, hence essential for female fertility (By similarity). Maternal factor required for proper zygotic genome activation and genome reprogramming (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H1-2","hgnc":"HGNC:4716","core":true,"core_annotation":{"hgnc":"HGNC:4716","symbol_at_source":"HIST1H1C","accession":"P16403","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":535,"hub_weight":0.2923526731023431,"quality":0.65,"programmes":["pubmed:27158335"],"pmids":["27158335"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:26581166, PubMed:38530350). Histone H1-2 is required for the condensation of nucleosome chains into higher-order structured fibers (PubMed:38530350). Compared to other histone H1 variants, H1-2 plays an essential role in nucleosome condensation: its absence leads to global chromatin decompaction, which is not observed when depleting other histone H1 variants (PubMed:38530350). Histone H1-2 also acts as a histone reader: specifically recognizes and binds histone H3 trimethylated at 'lys-27' (H3K27me3) (PubMed:26581166). Histones H1 also promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex, possibly by facilitating restoration of H3K27me3 post-replication (PubMed:37429872, PubMed:40516528). Together with histone H1-3, histone H1-2 acts as a regulator of splicing, most specifically exon skipping and intron retention events: histone H1-2 has a high affinity for exons and regulates splicing by affecting RNA polymerase II (RNAPII) elongation (PubMed:37922872). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (PubMed:38530350)","source":"project UniProt records20261017/18"},{"partner":"H1-3","hgnc":"HGNC:4717","core":true,"core_annotation":{"hgnc":"HGNC:4717","symbol_at_source":"HIST1H1D","accession":"P16402","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":322,"hub_weight":0.3666177875533832,"quality":0.65,"programmes":["pubmed:27158335"],"pmids":["27158335"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:37922872). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:40516528). Together with histone H1-3, histone H1-3 acts as a regulator of splicing, most specifically exon skipping and intron retention events: histone H1-3 has a high affinity for introns and regulates splicing by affecting RNA polymerase II (RNAPII) elongation (PubMed:37922872). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"NUCLEOLIN","hgnc":"HGNC:7667","core":true,"core_annotation":{"hgnc":"HGNC:7667","symbol_at_source":"NCL","accession":"P19338","function":"Histone chaperone","target":"histone, DNA, RNA","pmids":["16601700"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":695,"hub_weight":0.2590638800754199,"quality":0.65,"programmes":["pubmed:27158335"],"pmids":["27158335"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Nucleolin is the major nucleolar protein of growing eukaryotic cells. It is found associated with intranucleolar chromatin and pre-ribosomal particles. It induces chromatin decondensation by binding to histone H1. It is thought to play a role in pre-rRNA transcription and ribosome assembly. May play a role in the process of transcriptional elongation. Binds RNA oligonucleotides with 5'-UUAGGG-3' repeats more tightly than the telomeric single-stranded DNA 5'-TTAGGG-3' repeats","source":"project UniProt records20261017/18"},{"partner":"PRMT5","hgnc":"HGNC:10894","core":true,"core_annotation":{"hgnc":"HGNC:10894","symbol_at_source":"PRMT5","accession":"O14744","function":"Histone modification write","target":"histone","pmids":["18404153"],"complexes":"methylosome","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":407,"hub_weight":0.33077060082781123,"quality":0.65,"programmes":["pubmed:27158335"],"pmids":["27158335"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Chromosome; Golgi apparatus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Arginine methyltransferase that can both catalyze the formation of omega-N monomethylarginine (MMA) and symmetrical dimethylarginine (sDMA), with a preference for the formation of MMA (PubMed:10531356, PubMed:11152681, PubMed:11747828, PubMed:12411503, PubMed:15737618, PubMed:17709427, PubMed:20159986, PubMed:20810653, PubMed:21081503, PubMed:21258366, PubMed:21917714, PubMed:22269951, PubMed:33762328). Specifically mediates the symmetrical dimethylation of arginine residues in the small nuclear ribonucleoproteins Sm D1 (SNRPD1) and Sm D3 (SNRPD3); such methylation being required for the assembly and biogenesis of snRNP core particles (PubMed:11747828, PubMed:12411503, PubMed:17709427). Methylates SUPT5H and may regulate its transcriptional elongation properties (PubMed:12718890). May methylate the N-terminal region of MBD2 (PubMed:16428440). Mono- and dimethylates arginine residues of myelin basic protein (MBP) in vitro. May play a role in cytokine-activated transduction pathways. Negatively regulates cyclin E1 promoter activity and cellular proliferation. Methylates histone H2A and H4 'Arg-3' during germ cell development (By similarity). Methylates histone H3 'Arg-8', which may repress transcription (By similarity). Methylates the Piwi proteins (PIWIL1, PIWIL2 and PIWIL4), methylation of Piwi proteins being required for the interaction with Tudor domain-containing proteins and subsequent localization to the meiotic nuage (By similarity). Methylates RPS10 (PubMed:20159986). Attenuates EGF signaling through the MAPK1/MAPK3 pathway acting at 2 levels. First, monomethylates EGFR; this enhances EGFR 'Tyr-1197' phosphorylation and PTPN6 recruitment, eventually leading to reduced SOS1 phosphorylation (PubMed:21258366, PubMed:21917714). Second, methylates RAF1 and probably BRAF, hence destabilizing these 2 signaling proteins and reducing their catalytic activity (PubMed:21917714). Required for induction of E-selectin and VCAM-1, on the endothelial cells surface at sites of inflammation. Methylates HOXA9 (PubMed:22269951). Methylates and regulates SRGAP2 which is involved in cell migration and differentiation (PubMed:20810653). Acts as a transcriptional corepressor in CRY1-mediated repression of the core circadian component PER1 by regulating the H4R3 dimethylation at the PER1 promoter (By similarity). Methylates GM130/GOLGA2, regulating Golgi ribbon formation (PubMed:20421892). Methylates H4R3 in genes involved in glioblastomagenesis in a CHTOP- and/or TET1-dependent manner (PubMed:25284789). Symmetrically methylates POLR2A, a modification that allows the recruitment to POLR2A of proteins including SMN1/SMN2 and SETX. This is required for resolving RNA-DNA hybrids created by RNA polymerase II, that form R-loop in transcription terminal regions, an important step in proper transcription termination (PubMed:26700805). Along with LYAR, binds the promoter of gamma-globin HBG1/HBG2 and represses its expression (PubMed:25092918). Symmetrically methylates NCL (PubMed:21081503). Methylates p53/TP53; methylation might possibly affect p53/TP53 target gene specificity (PubMed:19011621). Involved in spliceosome maturation and mRNA splicing in prophase I spermatocytes through the catalysis of the symmetrical arginine dimethylation of SNRPB (small nuclear ribonucleoprotein-associated protein) and the interaction with tudor domain-containing protein TDRD6 (By similarity). Acts as a negative regulator of cGAS-STING signaling by mediating methylation of CGAS, preventing DNA-binding ability of CGAS (PubMed:33762328)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SPATA2L":{"coreEvidence":[],"near_known_relatives":[]}};
